//! Shared presentation primitives. Components retain their native state and events.
//! Installed by the host theme; absent configuration preserves upstream sizing.
use crate::{ActiveTheme, PixelsExt, Size};
use gpui::{px, relative, App, Global, SharedString, Styled};

/// App-wide control metrics in logical pixels, generated by the host theme.
#[derive(Clone, Debug)]
pub struct ControlStyle {
    pub height: f32,
    pub padding_x: f32,
    pub font_size: f32,
    pub font_family: SharedString,
    pub radius: f32,
    pub gap: f32,
}
impl Global for ControlStyle {}

impl ControlStyle {
    pub fn padding_y(&self) -> f32 {
        ((self.height - 2.0 - self.font_size * 1.25) * 0.5).max(0.0)
    }

    /// Shared geometry and typography. Multiline editors keep their own height.
    pub fn layout<T: Styled>(&self, element: T, multiline: bool) -> T {
        let element = element
            .px(px(self.padding_x))
            .py(px(self.padding_y()))
            .font_family(self.font_family.clone())
            .text_size(px(self.font_size))
            .line_height(relative(1.25))
            .gap(px(self.gap));
        if multiline {
            element
        } else {
            element
                .h(px(self.height))
                .min_h(px(self.height))
                .max_h(px(self.height))
        }
    }

    /// Shared field chrome and visual states. The control owns focus and events.
    pub fn surface<T: Styled>(
        &self,
        element: T,
        disabled: bool,
        focused: bool,
        bordered: bool,
        cx: &App,
    ) -> T {
        let element = element
            .rounded(px(self.radius))
            .bg(if disabled {
                cx.theme().muted
            } else {
                cx.theme().background
            })
            .text_color(if disabled {
                cx.theme().muted_foreground
            } else {
                cx.theme().foreground
            });
        if bordered {
            element.border_1().border_color(if focused && !disabled {
                cx.theme().ring
            } else {
                cx.theme().input
            })
        } else {
            element
        }
    }
}

/// Presentation role; geometry and event ownership remain with the component.
#[derive(Clone, Copy, Debug)]
pub enum SurfaceRole {
    Floating,
    Dialog,
    Sheet,
}

impl ControlStyle {
    pub fn size_factor(&self, size: Size) -> f32 {
        match size {
            Size::XSmall => 0.60,
            Size::Small => 0.80,
            Size::Large => 1.20,
            _ => 1.0,
        }
    }
    pub fn type_size(&self, size: Size) -> f32 {
        let scale = match size {
            Size::XSmall => 0.86,
            Size::Small => 0.93,
            Size::Large => 1.07,
            _ => 1.0,
        };
        self.font_size * scale
    }
    pub fn control_height(&self, size: Size) -> f32 {
        let requested = match size {
            Size::Size(height) => height.as_f32(),
            _ => self.height * self.size_factor(size),
        };
        requested.max(self.type_size(size) * 1.25 + 2.0)
    }
    pub fn typography<T: Styled>(&self, element: T, size: Size) -> T {
        element
            .font_family(self.font_family.clone())
            .text_size(px(self.type_size(size)))
            .line_height(relative(1.25))
    }
    /// Used by text/icon/loading/menu-trigger buttons. Variant colors stay in Button.
    pub fn action<T: Styled>(&self, element: T, size: Size, icon_only: bool, compact: bool) -> T {
        let height = self.control_height(size);
        let element = self.typography(element, size).h(px(height));
        if icon_only {
            element.w(px(height)).px(px(0.))
        } else {
            element.px(px(self.padding_x
                * self.size_factor(size)
                * if compact { 0.5 } else { 1.0 }))
        }
    }
    /// A shared label/indicator row for checkboxes, radios and switches.
    pub fn selection<T: Styled>(&self, element: T, size: Size, disabled: bool, cx: &App) -> T {
        self.typography(element, size)
            .min_h(px(self.control_height(size)))
            .gap(px(self.gap))
            .items_center()
            .text_color(if disabled {
                cx.theme().muted_foreground
            } else {
                cx.theme().foreground
            })
    }
    pub fn indicator_size(&self, size: Size) -> f32 {
        (self.font_size * 1.15).max(16.0) * self.size_factor(size)
    }
    /// Shared menu/list/sidebar row rhythm; no fixed maximum so content can wrap.
    pub fn item<T: Styled>(&self, element: T, size: Size) -> T {
        self.typography(element, size)
            .min_h(px(self.control_height(size) * 0.9))
            .px(px(self.padding_x))
            .py(px(self.gap * 0.5))
            .gap(px(self.gap))
    }
    /// Only the visual surface. Overlay bounds, anchors, focus and dismissal stay local.
    pub fn panel<T: Styled>(&self, element: T, role: SurfaceRole, cx: &App) -> T {
        let (background, foreground, radius) = match role {
            SurfaceRole::Floating => (
                cx.theme().popover,
                cx.theme().popover_foreground,
                self.radius,
            ),
            SurfaceRole::Dialog => (
                cx.theme().background,
                cx.theme().foreground,
                self.radius + 3.0,
            ),
            SurfaceRole::Sheet => (cx.theme().background, cx.theme().foreground, 0.0),
        };
        self.typography(element, Size::Medium)
            .bg(background)
            .text_color(foreground)
            .border_color(cx.theme().border)
            .rounded(px(radius))
    }
    /// Feedback content uses the same type and spacing scale; tone stays semantic.
    pub fn feedback<T: Styled>(&self, element: T, size: Size) -> T {
        self.typography(element, size)
            .px(px(self.padding_x * 1.33))
            .py(px(self.gap * self.size_factor(size)))
            .gap(px(self.gap))
    }
    pub fn badge<T: Styled>(&self, element: T, size: Size) -> T {
        self.typography(element, Size::XSmall)
            .px(px(self.gap * self.size_factor(size)))
            .py(px(self.gap * 0.25 * self.size_factor(size)))
    }
}

/// Header, virtual rows, stripe fillers, scrollbar offsets and skeleton rows must
/// all agree on this value. Keeping it here prevents visual/layout drift.
pub fn data_row_height(size: Size, cx: &App) -> gpui::Pixels {
    cx.try_global::<ControlStyle>()
        .map(|style| px(style.control_height(size) + style.gap * 0.5))
        .unwrap_or_else(|| size.table_row_height())
}

/// Shared tab policy for native controls. Disabling a focused control drops focus
/// immediately; enabling it restores the component's configured tab policy.
pub fn control_focus(
    handle: gpui::FocusHandle,
    disabled: bool,
    tab_stop: bool,
    tab_index: isize,
    window: &mut gpui::Window,
) -> gpui::FocusHandle {
    let handle = handle.tab_stop(tab_stop && !disabled).tab_index(tab_index);
    if disabled && handle.is_focused(window) {
        window.blur();
    }
    handle
}
